/**
 * Embeds the schema migrations of the pinned mq release into
 * src/migrations.generated.ts, the way the Go client embeds them through its
 * postgremq.dev/mq dependency. Runs on `npm ci` / `npm install` (prepare),
 * before `tsc` (npm run build) and as Jest's globalSetup. The generated file
 * is not committed.
 *
 * The pin is `postgremq.mq` in package.json. Once that mq version is released
 * its stamp migration (`NNNNNN_release_v<version>.up.sql`) exists, and only
 * the migrations up to and including it are embedded. Before then (an
 * unreleased pin) every migration is embedded; release checks refuse to
 * publish the package in that state.
 */
const fs = require('fs');
const path = require('path');

const PACKAGE = path.join(__dirname, '..', 'package.json');
const SOURCE = path.join(__dirname, '..', '..', 'mq', 'migrations');
const TARGET = path.join(__dirname, '..', 'src', 'migrations.generated.ts');
const UP_FILE = /^(\d+)_(.+)\.up\.sql$/;

/** The stamp migration name for an mq version (see mq/scripts/stamp_release.py). */
function stampName(version) {
  return 'release_v' + version.replace(/[^0-9A-Za-z]/g, '_');
}

/** The migrations bundled for the pinned mq version, in version order. */
function bundledMigrations() {
  const pin = JSON.parse(fs.readFileSync(PACKAGE, 'utf8')).postgremq?.mq;
  if (typeof pin !== 'string' || pin === '') {
    throw new Error(`${PACKAGE}: missing the "postgremq": { "mq": "<version>" } pin`);
  }
  const all = fs.readdirSync(SOURCE)
    .map((file) => UP_FILE.exec(file))
    .filter((match) => match !== null)
    .map(([file, version, name]) => ({ file, version: Number(version), name }))
    .sort((a, b) => a.version - b.version);
  if (all.length === 0) {
    throw new Error(`no migrations found in ${SOURCE}`);
  }
  for (let i = 1; i < all.length; i++) {
    if (all[i].version === all[i - 1].version) {
      throw new Error(`two migrations numbered ${all[i].version}: ${all[i - 1].file} and ${all[i].file}`);
    }
  }
  const stamp = all.find((m) => m.name === stampName(pin));
  const bundled = stamp ? all.filter((m) => m.version <= stamp.version) : all;
  return { pin, released: stamp !== undefined, migrations: bundled };
}

function embedMigrations() {
  const { pin, released, migrations } = bundledMigrations();
  const entries = migrations.map(({ file, version, name }) => ({
    version,
    name,
    sql: fs.readFileSync(path.join(SOURCE, file), 'utf8'),
  }));
  const content =
    '// Generated by scripts/embed-migrations.js from mq/migrations. Do not edit.\n' +
    `/** The pinned mq version (package.json "postgremq.mq")${released ? '' : ', not released yet'}. */\n` +
    `export const MQ_VERSION = ${JSON.stringify(pin)};\n` +
    'export const MIGRATIONS: ReadonlyArray<{ readonly version: number; readonly name: string; readonly sql: string }> = ' +
    JSON.stringify(entries, null, 2) +
    ';\n';
  const current = fs.existsSync(TARGET) ? fs.readFileSync(TARGET, 'utf8') : '';
  if (current !== content) {
    fs.writeFileSync(TARGET, content);
  }
}

module.exports = embedMigrations;
module.exports.bundledMigrations = bundledMigrations;
module.exports.stampName = stampName;

if (require.main === module) {
  embedMigrations();
}
